<a class="skip-link" href="#main">Skip to tasks</a><div class="app t01"><main class="board panel" id="main"><div class="brand"><h1>FocusFlow</h1><p class="tagline">A calm place for today's tasks.</p></div><div class="compose"><label class="sr-only" for="taskInput">New task</label><input id="taskInput" data-s02="input" type="text" placeholder="Add a task and press Enter" autocomplete="off"><button type="button" class="btn btn--solid" data-s02="add">Add task</button></div><ul class="list" data-s02="tasks" aria-live="polite" aria-label="Tasks"></ul><p class="empty" data-s02="empty">No tasks yet. Add one above.</p></main><aside class="rail panel" aria-label="Task statistics"><h2>Overview</h2><p class="counts"><span data-s02="count">0</span> tasks &middot; <span data-s02="active">0</span> active &middot; <span data-s02="completed">0</span> done</p><div class="filters" role="group" aria-label="Filter tasks"><button type="button" class="filter-btn" data-filter="all" aria-pressed="true">All</button><button type="button" class="filter-btn" data-filter="active" aria-pressed="false">Active</button><button type="button" class="filter-btn" data-filter="completed" aria-pressed="false">Completed</button></div><!-- s02:hook:html -->
